        return `<div class="blk blk-div${sCls}" ${dragAttr} data-b="${b.id}" style="width:100%;padding:${Number(b.mt || 8)}px 0 ${Number(b.mb || 8)}px"><div style="height:${Number(b.h || 1)}px;background:${E(b.color || '#cbd5e1')}"></div></div>`;
