        `${p.bgImg ? `<div class="pg-bg" style="position:fixed;inset:0;margin:0 auto;width:100%;max-width:1080px;background:${E(p.bg || '#ffffff')} url('${U(p.bgImg)}') center/cover no-repeat;z-index:0;pointer-events:none;transform:translateZ(0)"></div>` : ''}<main style="position:relative;z-index:1;background:${p.bgImg ? 'transparent' : E(p.bg || '#ffffff')}">${p.mode === 'detail' && p.detail ? detail(p.detail) : grid(p)}</main>` +
        `${!showHeader && h.floatInfo ? `<button class="float-i" data-a="menu" title="Shop Info">i</button>` : ''}`;
